  $j$[["validation", "/ˌvælɪˈdeɪʃn/", "sự khẳng định, xác nhận"], ["stack", "/stæk/", "chồng, xếp chồng"], ["glance over", "/ɡlɑːns ˈəʊvə/", "liếc qua"], ["pre-test", "/ˈpriː test/", "bài kiểm tra đầu khóa"], ["post-test", "/ˈpəʊst test/", "bài kiểm tra cuối khóa"], ["improve", "/ɪmˈpruːv/", "tiến bộ"], ["semester", "/sɪˈmestə/", "học kỳ"], ["be drawn to", "/bi drɔːn tuː/", "bị thu hút bởi"], ["dramatically", "/drəˈmætɪkli/", "đáng kể, vượt bậc"], ["approach", "/əˈprəʊtʃ/", "cách tiếp cận"], ["harangue", "/həˈræŋ/", "giảng giải dài dòng"], ["take advice seriously", "/teɪk ədˈvaɪs ˈsɪəriəsli/", "nghe lời khuyên nghiêm túc"], ["faithfully", "/ˈfeɪθfəli/", "đều đặn, trung thành"], ["adolescent", "/ˌædəˈlesnt/", "tuổi vị thành niên"], ["jargon", "/ˈdʒɑːɡən/", "thuật ngữ chuyên ngành"], ["exceptional", "/ɪkˈsepʃənl/", "xuất sắc, đặc biệt"], ["input-based", "/ˈɪnpʊt beɪst/", "dựa trên đầu vào"], ["the bulk of", "/ðə bʌlk ɒv/", "phần lớn"], ["analysis", "/əˈnæləsɪs/", "sự phân tích"], ["nag", "/næɡ/", "cằn nhằn"], ["cajole", "/kəˈdʒəʊl/", "dỗ dành, thuyết phục"], ["comprehensible input", "/ˌkɒmprɪˈhensəbl ˈɪnpʊt/", "đầu vào dễ hiểu"], ["thrilling", "/ˈθrɪlɪŋ/", "phấn khích"], ["quantitatively", "/ˈkwɒntɪtətɪvli/", "bằng con số, định lượng"], ["in other words", "/ɪn ˈʌðə wɜːdz/", "nói cách khác"], ["isolated incident", "/ˈaɪsəleɪtɪd ˈɪnsɪdənt/", "trường hợp cá biệt"], ["replicate", "/ˈreplɪkeɪt/", "lặp lại (kết quả)"], ["thorough", "/ˈθʌrə/", "đầy đủ, kỹ lưỡng"], ["phenomenon", "/fəˈnɒmɪnən/", "hiện tượng"], ["starkly", "/ˈstɑːkli/", "rõ ràng, rõ rệt"], ["exhort", "/ɪɡˈzɔːt/", "thúc giục"], ["plea", "/pliː/", "lời khẩn khoản"], ["rely on", "/rɪˈlaɪ ɒn/", "dựa vào"]]$j$::jsonb,
  $j$[["looking out the window", "nhìn ra cửa sổ"], ["the papers stacked in front of me", "chồng giấy trước mặt tôi"], ["I glance over the test scores again", "tôi liếc lại bảng điểm"], ["over the course of the semester", "trong suốt học kỳ"], ["improved by a couple of points", "tăng vài điểm"], ["my eyes are drawn to", "mắt tôi bị hút vào"], ["show a big jump", "tăng vọt"], ["What did they do differently?", "Họ đã làm gì khác?"], ["followed a different approach", "theo một cách khác"], ["took my advice seriously", "nghe lời khuyên của tôi nghiêm túc"], ["read for fun", "đọc cho vui"], ["The bulk of their study time", "Phần lớn thời gian học của họ"], ["breaking it apart", "mổ xẻ nó"], ["nag and cajole my students", "cằn nhằn và dỗ dành học viên"], ["in such dramatic fashion", "một cách ấn tượng như vậy"], ["In other words", "Nói cách khác"], ["This is not an isolated incident.", "Đây không phải trường hợp cá biệt."], ["In study after study", "Trong hết nghiên cứu này đến nghiên cứu khác"], ["Do not rely on textbooks.", "Đừng phụ thuộc vào sách giáo khoa."], ["those who do improve much more quickly", "những ai làm theo tiến bộ nhanh hơn nhiều"]]$j$::jsonb,
  $j$[["S + be + V-ing, + V-ing ...", "I'm sitting on the bus, listening to music.", "Tôi đang ngồi trên xe buýt, nghe nhạc.", "sitting|looking"], ["S + improved by + amount", "My score improved by ten points.", "Điểm của tôi tăng mười điểm.", "improved by"], ["S + improved + dramatically more than + noun", "Sales improved dramatically more than we expected.", "Doanh số tăng vượt xa dự đoán của chúng tôi.", "more than"], ["Since + clause, S + focus on + noun", "Since we have little time, we focus on the main points.", "Vì có ít thời gian, chúng ta tập trung vào ý chính.", "since"], ["S + took + someone's advice seriously", "I took my doctor's advice seriously.", "Tôi nghe lời bác sĩ một cách nghiêm túc.", "advice seriously"], ["The bulk of + noun + was spent + V-ing", "The bulk of my day was spent answering emails.", "Phần lớn ngày của tôi dành để trả lời email.", "the bulk of"], ["Plenty of research shows that + clause", "Plenty of research shows that sleep matters.", "Rất nhiều nghiên cứu cho thấy giấc ngủ quan trọng.", "research shows"], ["..., which is why + clause", "I was tired, which is why I went to bed early.", "Tôi mệt, đó là lý do tôi đi ngủ sớm.", "which is why"], ["It was thrilling to see + noun + V3", "It was thrilling to see my work published.", "Thật phấn khích khi thấy tác phẩm của mình được xuất bản.", "thrilling to see"], ["In other words, + clause", "He's busy. In other words, he can't come.", "Anh ấy bận. Nói cách khác, anh ấy không đến được.", "in other words"], ["This is not an isolated + noun", "This is not an isolated case.", "Đây không phải trường hợp cá biệt.", "isolated"], ["noun + after + noun", "Day after day, he practiced.", "Ngày qua ngày, anh ấy luyện tập.", "after"], ["Do not + V", "Do not give up.", "Đừng bỏ cuộc.", "do not"], ["Those who + V + V + more quickly than those who don't", "Those who practice improve faster than those who don't.", "Ai luyện tập sẽ tiến bộ nhanh hơn người không luyện.", "those who"]]$j$::jsonb
)
