  $j$[["worthy", "/ˈwɜːði/", "xứng đáng"], ["trapped", "/træpt/", "mắc kẹt"], ["stare at", "/steər æt/", "nhìn chằm chằm"], ["glacial pace", "/ˈɡleɪʃl peɪs/", "tốc độ chậm như rùa"], ["mind-numbing", "/ˈmaɪnd ˌnʌmɪŋ/", "nhàm chán đến tê liệt đầu óc"], ["routine", "/ruːˈtiːn/", "thói quen hằng ngày"], ["miserable", "/ˈmɪzrəbl/", "khổ sở"], ["make a living", "/meɪk ə ˈlɪvɪŋ/", "kiếm sống"], ["autonomy", "/ɔːˈtɒnəmi/", "quyền tự chủ"], ["degrading", "/dɪˈɡreɪdɪŋ/", "hạ thấp phẩm giá"], ["capture", "/ˈkæptʃə/", "khắc họa, nắm bắt"], ["sterility", "/stəˈrɪləti/", "sự khô khan, vô hồn"], ["pointlessness", "/ˈpɔɪntləsnəs/", "sự vô nghĩa"], ["degradation", "/ˌdeɡrəˈdeɪʃn/", "sự hạ thấp phẩm giá"], ["crush", "/krʌʃ/", "nghiền nát"], ["depressed", "/dɪˈprest/", "chán nản"], ["oppressive", "/əˈpresɪv/", "áp bức"], ["misery", "/ˈmɪzəri/", "nỗi khổ"], ["insincerity", "/ˌɪnsɪnˈserəti/", "sự giả dối"], ["drab", "/dræb/", "tẻ nhạt, xám xịt"], ["humiliation", "/hjuːˌmɪliˈeɪʃn/", "sự nhục nhã"], ["quest", "/kwest/", "cuộc tìm kiếm"], ["livelihood", "/ˈlaɪvlihʊd/", "sinh kế, cách kiếm sống"], ["administrator", "/ədˈmɪnɪstreɪtə/", "người quản lý"], ["a whiff of", "/ə wɪf ɒv/", "thoáng chút"], ["self-employment", "/ˌself ɪmˈplɔɪmənt/", "tự làm chủ"], ["principle", "/ˈprɪnsəpl/", "nguyên tắc"], ["launch", "/lɔːntʃ/", "khởi động, lập ra"], ["be sick of", "/bi sɪk ɒv/", "chán ngấy"], ["pursue", "/pəˈsjuː/", "theo đuổi"], ["guarantee", "/ˌɡærənˈtiː/", "sự đảm bảo"], ["specter", "/ˈspektə/", "bóng ma"], ["terrify", "/ˈterɪfaɪ/", "làm khiếp sợ"], ["ask out", "/ɑːsk aʊt/", "mời đi chơi, hẹn hò"], ["antidote", "/ˈæntidəʊt/", "thuốc giải"]]$j$::jsonb,
  $j$[["There I was, trapped in a tiny office", "Tôi ở đó, mắc kẹt trong một văn phòng bé tí"], ["staring at the clock", "nhìn chằm chằm vào đồng hồ"], ["Time seemed to go at a glacial pace.", "Thời gian trôi chậm như rùa bò."], ["I sat like that for hours", "Tôi ngồi như thế hàng giờ"], ["the same mind-numbing routine", "cùng một thói quen nhàm chán"], ["the most miserable job I've ever had", "công việc khổ sở nhất tôi từng làm"], ["make a living", "kiếm sống"], ["It was very funny because it was so true.", "Rất buồn cười vì nó quá thật."], ["factories of degradation", "những nhà máy hạ thấp phẩm giá"], ["the greatest source of misery", "nguồn đau khổ lớn nhất"], ["I've been on a quest for a better livelihood.", "Tôi luôn đi tìm cách kiếm sống tốt hơn."], ["a whiff of command and control", "thoáng mùi ra lệnh và kiểm soát"], ["be your own boss", "tự làm chủ"], ["live according to your own principles", "sống theo nguyên tắc của chính mình"], ["I was sick of", "Tôi chán ngấy"], ["take the risk and follow my heart", "chấp nhận rủi ro và làm theo trái tim"], ["There are no guarantees.", "Không có gì đảm bảo cả."], ["The specter of failure always hangs over you.", "Bóng ma thất bại luôn lơ lửng trên đầu bạn."], ["both terrify and inspire you", "vừa khiến bạn sợ vừa truyền cảm hứng"], ["don't let it stop you", "đừng để nó ngăn cản bạn"], ["the best antidote to fear is action", "liều thuốc giải tốt nhất cho nỗi sợ là hành động"]]$j$::jsonb,
  $j$[["There I was, + V-ing / adj ...", "There I was, standing in the rain.", "Tôi ở đó, đứng dưới mưa.", "there i was"], ["S + seemed to + V", "The day seemed to last forever.", "Ngày hôm đó dường như dài vô tận.", "seemed to"], ["It looked like + clause", "It looked like he was asleep.", "Trông như thể anh ấy đang ngủ.", "looked like"], ["the most + adj + noun + I've ever + V3", "This is the most delicious cake I've ever eaten.", "Đây là chiếc bánh ngon nhất tôi từng ăn.", "the most|ever"], ["Is it possible to + V?", "Is it possible to learn English in a year?", "Có thể học tiếng Anh trong một năm không?", "is it possible"], ["Does + noun + have to be + adj?", "Does homework have to be boring?", "Bài tập về nhà có nhất thiết phải nhàm chán không?", "have to be"], ["S + captured + noun + perfectly", "The photo captured her smile perfectly.", "Bức ảnh lột tả nụ cười của cô ấy thật hoàn hảo.", "captured"], ["S + have been on a quest for + noun", "I've been on a quest for the perfect coffee.", "Tôi đang đi tìm ly cà phê hoàn hảo.", "quest for"], ["..., or + S + will never be able to + V", "Save money now, or you will never be able to buy a house.", "Hãy tiết kiệm ngay, nếu không bạn sẽ chẳng bao giờ mua được nhà.", "never be able to"], ["S + was sick of + V-ing / noun", "I was sick of waiting.", "Tôi chán ngấy việc chờ đợi.", "sick of"], ["S + should both + V + and + V + someone", "A good teacher should both challenge and support you.", "Giáo viên giỏi vừa thử thách vừa hỗ trợ bạn.", "both"], ["If you don't + V, it's probably not + noun", "If you don't enjoy it, it's probably not the right job.", "Nếu bạn không thích, có lẽ đó không phải công việc phù hợp.", "probably not"], ["My best advice to you is to + V", "My best advice to you is to start now.", "Lời khuyên tốt nhất của tôi là hãy bắt đầu ngay.", "best advice"], ["Whatever + noun, + imperative", "Whatever your problem, don't give up.", "Dù vấn đề của bạn là gì, đừng bỏ cuộc.", "whatever"]]$j$::jsonb
